const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tags=s=>s.types.map(t=>`<span class="tag" style="--type:${TYPE_COLORS[t]}">${entity('types',t)}</span>`).join('');
const num=n=>String(n).padStart(3,'0');
export class UI{
 constructor(game){this.game=game;game.ui=this;this.previews=[];this.previewEpoch=0;this.selectedDex=1;this.dexFilter='all';this.dexSearch='';this.updateTimer=0;this.assetId=1;this.focusOrigin=null;this.startScreen=new StartScreen(this);this.bind();localizeDOM();}
 bind(){$('#hud-details').onclick=()=>{const open=$('#hud').classList.toggle('hud-details-open');this.minimapExpanded=open;$('#hud-details').textContent=open?'정보 −':'정보 +';$('#hud-details').setAttribute('aria-expanded',String(open));$('#hud-details').setAttribute('aria-label',open?'상세 정보 접기':'상세 정보 펼치기');};$('#touch-skills').onclick=()=>{this.skillBarOverride=!$('#hud').classList.contains('skills-open');this.updateTimer=0;};document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>this.game.openPanel(b.dataset.panel));$('#new-game').onclick=()=>this.game.startSelection();$('#continue').onclick=()=>this.startScreen.continue();$('#close-panel').onclick=()=>this.game.closePanel();$('#throw-button').onclick=()=>this.game.throwBall();$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')this.game.closePanel();});$('#panel').addEventListener('keydown',e=>{if(e.key!=='Tab')return;const buttons=[...$('#panel').querySelectorAll('button:not(:disabled),input,select,a[href]')].filter(e=>e.offsetParent!==null);if(!buttons.length)return;const first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});window.addEventListener('resize',()=>{if(this.game.panel==='dex')requestAnimationFrame(()=>{if(this.game.panel!=='dex')return;this.fitDexGrid();for(const p of this.previews){const canvas=p.renderer.domElement;if(canvas.id!=='dex-preview')continue;const w=canvas.clientWidth,h=canvas.clientHeight;if(w&&h){p.renderer.setSize(w,h,false);p.camera.aspect=w/h;p.camera.updateProjectionMatrix();}}});});}
 loading(message){this.startScreen.suspend();this.startScreen.translate();$('#loading').classList.remove('hidden');$('#load-message').textContent=tx(message);this.progress(0,message);$('#title').classList.add('hidden');$('#starter').classList.add('hidden');$('#hud').classList.add('hidden');}
 progress(value,message){$('#load-progress').style.width=`${Math.round(value*100)}%`;$('#load-message').textContent=tx(message);if(value>=1)setTimeout(()=>$('#loading').classList.add('hidden'),250);}
 ready(){this.progress(1,t('loading.welcome'));this.startScreen.ready();}

 loadError(error){$('#load-message').textContent=t('loading.stopped',{error:error.message});}
 showStarter(){this.closePanel();this.startScreen.showStarter();}


 confirmNewGame(){this.game.panel='new-game';this.shell(t('newGame.heading'),t('newGame.kicker'));$('#panel-body').innerHTML='<p>Your current expedition will be replaced when you select a new partner. Export a copy first if you want to keep it.</p><div class="pause-actions"><button id="export-before-new">Export current save</button><button id="confirm-new">Begin a new expedition</button><button id="cancel-new">Keep exploring</button></div>';localizeDOM($('#panel'));$('#export-before-new').onclick=()=>this.exportSave();$('#confirm-new').onclick=()=>{this.game.closePanel();this.game.enterSelection();};$('#cancel-new').onclick=()=>this.game.closePanel();}
 field(){this.startScreen.suspend();$('#loading').classList.add('hidden');$('#title').classList.add('hidden');$('#starter').classList.add('hidden');$('#hud').classList.remove('hidden');this.movesChanged();}
 regionChanged(biome){$('#region-name').textContent=biome.name;$('#region-kicker').textContent=t('panel.fieldNotes',{number:String(this.game.biomes.indexOf(biome)+1).padStart(2,'0')});}
 movesChanged(){const g=this.game;if(!g.activeMoves)return;$('#moves').innerHTML=g.activeMoves.map((m,i)=>`<button class="move" data-move="${i}" style="--type:${TYPE_COLORS[m.type]}" title="${esc(m.effectDescription||m.description||m.name)}"><span class="cooldown"></span><kbd>${i+1}</kbd><em>${m.type==='electric'?'ϟ':m.type==='water'?'≈':m.type==='fire'?'♨':m.type==='grass'?'❧':'◇'}</em><strong>${esc(m.name)}</strong></button>`).join('');document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>g.attack(Number(b.dataset.move)));this.fitMoveLabels();document.fonts?.ready.then(()=>this.fitMoveLabels());}
 fitMoveLabels(){const canvas=this.nameMeasure??=document.createElement('canvas'),ctx=canvas.getContext('2d');document.querySelectorAll('[data-move] strong').forEach(el=>{const name=this.game.activeMoves[Number(el.closest('[data-move]').dataset.move)]?.name;if(!name)return;const width=el.clientWidth,key=name+':'+width+':'+document.fonts?.status;if(el.dataset.fit===key)return;el.dataset.fit=key;const font=getComputedStyle(el);ctx.font='600 11px '+font.fontFamily;const lines=balancedMoveName(name,width,text=>ctx.measureText(text).width),max=Math.max(...lines.map(text=>ctx.measureText(text).width));el.style.fontSize=Math.min(11,11*width/Math.max(width,max))+'px';el.innerHTML=lines.map(line=>'<span>'+esc(line)+'</span>').join('');el.setAttribute('aria-label',name);});}
 toast(message,detail='',warn=false){const el=document.createElement('div');el.className='toast'+(warn?' warn':'');el.innerHTML=`${esc(tx(message))}${detail?`<small>${esc(tx(detail))}</small>`:''}`;$('#toast-stack').append(el);while($('#toast-stack').children.length>2)($('#toast-stack').querySelector('.toast:not(.warn)')||$('#toast-stack').firstChild).remove();setTimeout(()=>el.remove(),warn?6500:3000);}
 saved(){$('#save-note').textContent=t('save.saved');clearTimeout(this.saveTimer);this.saveTimer=setTimeout(()=>$('#save-note').textContent='',2300);}
 cinematic(kicker,name,description,duration=3){$('#cinematic').classList.remove('hidden');$('#cinematic-kicker').textContent=tx(kicker);$('#cinematic-name').textContent=name;$('#cinematic-description').textContent=tx(description);clearTimeout(this.cinematicTimer);this.cinematicTimer=setTimeout(()=>$('#cinematic').classList.add('hidden'),duration*1000);}
 damage(actor,damage,effectiveness,critical=false,tier='light'){if(!damage&&effectiveness!==0)return;const point=this.game.world.project(actor.model.position.clone().add(new THREE.Vector3(0,actor.model.userData.height+.7,0)));if(!point.visible)return;this.damageFloats??=new WeakMap();const active=(this.damageFloats.get(actor)||[]).filter(el=>el.isConnected);while(active.length>=3)active.shift().remove();const el=document.createElement('div');el.className='damage-number '+tier+(critical?' critical':'')+(effectiveness>1?' effective':'');const hint=effectiveness===0?t('ui.immune'):[critical?t('ui.criticalShort'):'',effectiveness>1?t('ui.effectiveShort'):effectiveness<1?t('ui.resistedShort'):''].filter(Boolean).join(' · ');el.innerHTML=(hint?'<small>'+esc(hint)+'</small>':'')+(effectiveness===0?'':'<b>'+damage+'</b>');el.setAttribute('aria-label',hint+' '+damage);el.style.left=(point.x+(active.length-1)*22)+'px';el.style.top=(point.y-active.length*16)+'px';$('#labels').append(el);active.push(el);this.damageFloats.set(actor,active);setTimeout(()=>el.remove(),850);}
 endCinematic(){clearTimeout(this.cinematicTimer);$('#cinematic').classList.add('hidden');}
 impactEmphasis(type,critical,tier){const v=document.querySelector('#vignette');v.style.setProperty('--impact-color',TYPE_COLORS[type]);v.classList.remove('impact-emphasis');void v.offsetWidth;v.classList.add('impact-emphasis');setTimeout(()=>v.classList.remove('impact-emphasis'),260);}
 statusApplied(actor,status){this.toast(t('ui.status',{pokemon:actor.species.name,status:entity('statuses',status)}));}
 cooldownReady(slot){const b=document.querySelector(`[data-move="${slot}"]`);b?.classList.add('move-ready');setTimeout(()=>b?.classList.remove('move-ready'),450);}
 routeUnlocked(){document.querySelector('#journal-button')?.classList.add('route-unlocked');setTimeout(()=>document.querySelector('#journal-button')?.classList.remove('route-unlocked'),1700);}
 cleanupPreviews(){this.previewEpoch++;for(const p of this.previews){p.model?.userData.release?.();p.renderer.dispose();p.renderer.forceContextLoss();p.ground?.geometry.dispose();p.ground?.material.dispose();}this.previews=[];}
 closePanel(){this.cleanupPreviews();$('#modal-backdrop').classList.add('hidden');this.focusOrigin?.focus?.();this.startScreen.resume();}
 shell(title,kicker=t('panel.journal')){this.cleanupPreviews();$('#panel').classList.remove('move-choice-panel');$('#panel').dataset.panel=this.game.panel||'';if($('#modal-backdrop').classList.contains('hidden'))this.focusOrigin=document.activeElement;$('#modal-backdrop').classList.remove('hidden');$('#panel-title').textContent=title;$('#panel-kicker').textContent=tx(kicker);$('#panel-body').innerHTML='';$('#close-panel').focus();}
 panel(name){const titles={expeditions:'지역 탐사 기록',moves:t('moves.heading'),dex:t('panel.dex'),party:t('panel.party'),bag:t('panel.bag'),map:t('panel.map'),settings:t('panel.settings'),pause:t('panel.pause'),credits:t('panel.credits'),research:t('panel.research'),shop:t('panel.shop'),assets:t('panel.assets')};this.shell(titles[name]||niceLocal(name),name==='dex'?t('panel.dexCount',{count:num(caughtCount(this.game.save))}):name==='assets'?t('panel.assetKicker'):t('app.fieldEdition'));this[name]?.();localizeDOM($('#panel'));}
 refreshPanel(){if(this.game.panel)this.panel(this.game.panel);}
 partnerArtwork(player){
  const id=player.species.id,shiny=Boolean(player.pokemon.shiny),key=id+':'+shiny,button=$('.partner-portrait'),image=$('#partner-portrait');
  const label=player.species.name+(shiny?' ✦':'')+' · '+t('panel.party')+(player.status?' · '+niceLocal(player.status):'');
  button.setAttribute('aria-label',label);button.setAttribute('data-i18n-aria-label',label);button.title=label;button.setAttribute('data-i18n-title',label);image.alt=player.species.name;button.classList.toggle('shiny',shiny);
  if(this.portraitKey===key&&(button.dataset.state!=='unavailable'||performance.now()<(this.portraitRetryAt||0)))return;this.portraitKey=key;image.hidden=true;image.removeAttribute('src');button.dataset.state='loading';button.dataset.species=String(id);button.dataset.shiny=String(shiny);
  this.portraits??=new PartnerPortraits(this.game.world.renderer,this.game.resources);
  this.portraits.image(id,shiny).then(src=>{if(this.portraitKey!==key)return;image.src=src;image.hidden=false;button.dataset.state='ready';}).catch(error=>{if(this.portraitKey===key){button.dataset.state='unavailable';this.portraitRetryAt=performance.now()+30000;}console.warn('Partner portrait unavailable',id,error);});
 }
 async preview(canvas,id,shiny=false,options={}){const token=this.previewEpoch;const renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));const w=canvas.clientWidth||300,h=canvas.clientHeight||220;renderer.setSize(w,h,false);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;renderer.shadowMap.enabled=true;const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(34,w/h,.05,40);scene.add(new THREE.HemisphereLight(0xfff7da,0x548978,3));const light=new THREE.DirectionalLight(0xffffff,3);light.position.set(3,6,4);scene.add(light);const ground=new THREE.Mesh(new THREE.CircleGeometry(2,48),new THREE.MeshBasicMaterial({color:0xacc09a,transparent:true,opacity:.08,side:THREE.DoubleSide}));ground.rotation.x=-Math.PI/2;ground.position.y=.005;scene.add(ground);const p={renderer,scene,camera,model:null,ground,angle:.55,animation:null,elapsed:0};this.previews.push(p);try{const model=await this.game.resources.create(id,{shiny,maxDimension:3.2});if(token!==this.previewEpoch){model.userData.release();return;}p.model=model;scene.add(model);const dimensions=model.userData.dimensions,factor=(options.modelSize??2.4)/Math.max(dimensions.x,dimensions.y,dimensions.z,.1);model.scale.setScalar(factor);const height=(model.userData.height||2)*factor;camera.position.set(0,height*.5+1,5.8);camera.lookAt(0,height*.48,0);model.rotation.y=.55;if(options.interactive!==false){let last=null;canvas.addEventListener('pointerdown',e=>{last=e.clientX;canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(last!==null){p.angle+=(e.clientX-last)*.013;last=e.clientX;}});canvas.addEventListener('pointerup',()=>last=null);canvas.addEventListener('pointercancel',()=>last=null);}return p;}catch(e){if(token===this.previewEpoch)this.toast(t('dex.previewFailed'),e.message,true);return p;}}
 dex(){const g=this.game,ko=currentLocale()==='ko-KR';$('#panel-body').innerHTML=`<div class="panel-toolbar"><input id="dex-search" aria-label="${esc(t('dex.searchAria'))}" placeholder="${esc(t('dex.searchPlaceholder'))}" value="${esc(this.dexSearch)}"><select id="dex-filter" aria-label="${esc(t('dex.filterAria'))}"><option value="all">${ko?'전체 151종':'All 151'}</option><option value="uncaught">${ko?'미등록':'Unregistered'}</option><option value="unseen">${ko?'미발견':'Unknown'}</option><option value="seen">${ko?'발견':'Seen'}</option><option value="caught">${ko?'등록':'Registered'}</option><option value="shiny">${ko?'이로치 등록':'Shiny registered'}</option></select></div><div class="dex-legend"><span>${ko?'컬러: 등록 · 회색: 미등록':'Colour: registered · Grey: unregistered'}</span><b>${t('dex.progress',{ seen:Object.values(g.save.dex).filter(x=>x.seen).length,caught:caughtCount(g.save) })}</b></div><div class="dex-layout"><section class="dex-list" aria-label="${ko?'포켓몬 목록':'Pokémon list'}"><div id="dex-grid" class="dex-grid"></div><div class="dex-list-footer" id="dex-scroll-hint">${ko?'더 보기 · 위아래로 스크롤':'Scroll to browse more'}</div></section><aside id="dex-detail" class="dex-detail"></aside></div>`;$('#dex-filter').value=this.dexFilter;$('#dex-search').oninput=e=>{this.dexSearch=e.target.value;$('#dex-grid').scrollTop=0;this.renderDexGrid();};$('#dex-filter').onchange=e=>{this.dexFilter=e.target.value;$('#dex-grid').scrollTop=0;this.renderDexGrid();};this.renderDexGrid();this.dexDetail(this.selectedDex);}
 renderDexGrid(){const g=this.game,q=this.dexSearch.toLowerCase(),ko=currentLocale()==='ko-KR',grid=$('#dex-grid'),scroll=grid.scrollTop;const list=g.species.filter(s=>{const d=g.save.dex[s.id]||{};return (!q||s.name.toLowerCase().includes(q)||s.englishName?.toLowerCase().includes(q)||num(s.id).includes(q))&&(this.dexFilter==='all'||this.dexFilter==='uncaught'&&!d.caught||this.dexFilter==='unseen'&&!d.seen||this.dexFilter==='seen'&&d.seen||this.dexFilter==='caught'&&d.caught||this.dexFilter==='shiny'&&d.shinyCaught);});grid.innerHTML=list.length?list.map(s=>{const d=g.save.dex[s.id]||{},status=d.caught?(ko?'등록':'Registered'):d.seen?(ko?'발견':'Seen'):(ko?'미등록':'Unregistered');return `<button class="dex-card ${d.caught?'caught':d.seen?'seen':'unknown'} ${s.id===this.selectedDex?'selected':''}" data-dex="${s.id}" aria-pressed="${s.id===this.selectedDex}" aria-label="#${num(s.id)} ${esc(s.name)} · ${d.caught?(ko?'등록':'Registered'):(ko?'미등록':'Unregistered')}${d.shinyCaught?(ko?' · 이로치 등록':' · Shiny registered'):''}"><small class="dex-number">#${num(s.id)}</small>${d.shinyCaught?`<span class="dex-shiny" title="${ko?'이로치 등록':'Shiny registered'}" aria-hidden="true">✦</span>`:''}<span class="dex-art"><img src="./assets/dex/${num(s.id)}.png" alt="" loading="lazy" decoding="async" width="160" height="160"></span><strong>${esc(s.name)}</strong><span class="dex-status">${d.caught?'✓ ':''}${status}</span></button>`;}).join(''):`<p class="notice">${ko?'검색 조건에 맞는 포켓몬이 없어요.':'No Pokémon match this filter.'}</p>`;this.fitDexGrid(scroll);grid.querySelectorAll('[data-dex]').forEach(b=>b.onclick=()=>{this.selectedDex=Number(b.dataset.dex);this.renderDexGrid();this.dexDetail(this.selectedDex);grid.querySelector('[data-dex="'+this.selectedDex+'"]')?.focus({preventScroll:true});});}
 fitDexGrid(scroll){const grid=$('#dex-grid');if(!grid)return;const css=getComputedStyle(grid),row=parseFloat(css.getPropertyValue('--dex-card-height')),gap=parseFloat(css.rowGap)||0,columns=css.gridTemplateColumns.split(' ').length,count=grid.querySelectorAll('[data-dex]').length,totalRows=Math.max(1,Math.ceil(count/columns)),rows=Math.min(totalRows,Number(css.getPropertyValue('--dex-row-cap'))||3),padding=(parseFloat(css.paddingTop)||0)+(parseFloat(css.paddingBottom)||0),previous=scroll??grid.scrollTop;grid.style.height=(rows*row+(rows-1)*gap+padding)+'px';grid.dataset.visibleRows=String(rows);grid.scrollTop=Math.round(previous/(row+gap))*(row+gap);const hint=$('#dex-scroll-hint');if(hint)hint.hidden=totalRows<=rows;const cap=Number(css.getPropertyValue('--dex-row-cap'))||3;grid.closest('.dex-layout').style.setProperty('--dex-list-height',(cap*row+(cap-1)*gap+padding+27)+'px');}
 dexDetail(id){this.cleanupPreviews();const g=this.game,s=g.byId.get(id),d=g.save.dex[id]||{},ev=s.evolutions.map(e=>`${g.byId.get(e.to).name} · ${e.minLevel?'Lv. '+e.minLevel:niceLocal(e.item)}`).join('<br>');$('#dex-detail').classList.toggle('unregistered',!d.caught);$('#dex-detail').innerHTML=`<div class="dex-profile">${d.seen?`<canvas class="preview-canvas" id="dex-preview" aria-label="${t('dex.rotateAria',{ pokemon:s.name })}"></canvas>`:`<img class="preview-canvas dex-static-preview" id="dex-preview" src="./assets/dex/${num(id)}.png" alt="${esc(s.name)}" width="160" height="160">`}<div class="dex-identity"><small>${t('common.number',{ number:num(id) })} · ${d.shinyCaught?t('dex.shinyCaughtUpper'):d.caught?t('dex.caughtUpper'):d.seen?t('dex.seenUpper'):t('dex.unknownUpper')}</small><h2>${d.seen?esc(s.name):t('dex.awaiting')}</h2>${tags(s)}<p>${esc(s.genus)} · ${s.height} m · ${s.weight} kg</p></div></div><h3>Where to look</h3><p>${esc(s.habitatHint)}</p><button id="track-habitat">${t('exp.track')}</button><h3>Evolution family</h3><p>${s.evolvesFrom?'From '+g.byId.get(s.evolvesFrom)?.name+'<br>':''}${ev||t('dex.finalEvolution')}</p>${d.seen?Object.entries(s.baseStats).map(([name,n])=>`<div class="stat-row"><span>${{specialAttack:'Sp. Atk',specialDefense:'Sp. Def'}[name]||niceLocal(name)}</span><i style="width:${Math.min(100,n/2)}%"></i><span>${n}</span></div>`).join(''):''}${d.shinySeen?'<button id="dex-shiny" class="text-button">Switch normal / shiny</button>':''}${d.seen?'<small>Drag the model to rotate.</small>':`<small>${currentLocale()==='ko-KR'?'아직 만나지 않은 포켓몬이에요.':'You have not encountered this Pokémon yet.'}</small>`}`;if(d.seen){this.preview($('#dex-preview'),id,d.shinyCaught,{modelSize:2.1}).then(p=>{if($('#dex-shiny')){let shiny=d.shinyCaught;$('#dex-shiny').onclick=()=>{shiny=!shiny;p?.model?.userData.setShiny(shiny);};}});}document.querySelector('#track-habitat')?.addEventListener('click',()=>g.expedition.trackSpecies(id));localizeDOM($('#dex-detail'));}
 party(){const g=this.game,party=g.save.party.map(uid=>g.save.collection.find(p=>p.uid===uid)),camp=this.partyTab==='camp';
 $('#panel-body').innerHTML=`<div class="party-tabs" role="tablist" aria-label="친구 관리"><button id="party-tab-partners" role="tab" aria-selected="${!camp}">파트너 ${party.length}/6</button><button id="party-tab-camp" role="tab" aria-selected="${camp}">캠프 교체 · ${g.save.collection.length-party.length}</button></div><section id="partner-list" ${camp?'hidden':''}><p class="section-caption">동행 친구를 눌러 기술·도구·진화를 관리하세요.</p><div class="party-list">${party.map((p,i)=>{const species=g.byId.get(p.id),ev=evolutionOptions(p,species,g.save),full=p.hp>=maxHP(species,p.level)&&!p.status;return `<details class="party-entry ${i===0?'active':''}" data-party-uid="${p.uid}" ${this.partyDetailUid===p.uid?'open':''}><summary><img src="./assets/dex/${num(p.id)}.png" alt="" width="44" height="44"><span class="party-summary-name"><b>${esc(species.name)}${p.shiny?' ✦':''}</b><small>${i===0?'현재 파트너':(i+1)+'번 자리'} · LV ${p.level}${p.status?' · '+niceLocal(p.status):''}</small></span><span class="party-summary-health"><b>${Math.ceil(p.hp)} / ${maxHP(species,p.level)}</b><span class="hp-track"><i style="width:${p.hp/maxHP(species,p.level)*100}%"></i></span></span></summary><div class="party-entry-detail">${tags(species)}<p>경험치 ${Math.round(p.exp)} / ${expNeeded(p.level)}${ev.length?' · 진화 가능':''}</p><div class="party-entry-actions">${i!==0?`<button data-switch="${p.uid}" ${p.hp<=0?'disabled':''}>Travel together</button>`:''}<button data-manage-moves="${p.uid}">${t('moves.manage')}</button><button data-heal="${p.uid}" ${!g.save.inventory.potion||p.hp<=0||full?'disabled':''}>${t('party.potion',{count:g.save.inventory.potion||0})}</button><button data-candy="${p.uid}" ${!g.save.inventory['rare-candy']||p.level>=100?'disabled':''}>${t('party.candy',{count:g.save.inventory['rare-candy']||0})}</button>${ev.map(e=>`<button data-evolve="${p.uid}:${e.to}">${t('party.evolve',{pokemon:g.byId.get(e.to).name})}</button>`).join('')}</div>${!ev.length&&species.evolutions.length?`<small>다음 진화 조건: ${species.evolutions.map(e=>e.minLevel?'LV '+e.minLevel:niceLocal(e.item)).join(' / ')}</small>`:''}</div></details>`;}).join('')}</div></section><section id="camp-manager" ${camp?'':'hidden'}></section>`;
 $('#party-tab-partners').onclick=()=>{this.partyTab='partners';this.party();};$('#party-tab-camp').onclick=()=>{this.partyTab='camp';this.party();};
 document.querySelectorAll('[data-party-uid]').forEach(e=>e.ontoggle=()=>{if(e.open){this.partyDetailUid=e.dataset.partyUid;for(const other of document.querySelectorAll('[data-party-uid]'))if(other!==e)other.open=false;}else if(this.partyDetailUid===e.dataset.partyUid)this.partyDetailUid=null;});
 renderCamp(this);document.querySelectorAll('[data-switch]').forEach(b=>b.onclick=()=>g.switchPartner(b.dataset.switch).catch(e=>g.fail(e)));document.querySelectorAll('[data-manage-moves]').forEach(b=>b.onclick=()=>g.manageMoves(b.dataset.manageMoves));document.querySelectorAll('[data-heal]').forEach(b=>b.onclick=()=>g.useItem('potion',b.dataset.heal));document.querySelectorAll('[data-candy]').forEach(b=>b.onclick=()=>g.useItem('rare-candy',b.dataset.candy));document.querySelectorAll('[data-evolve]').forEach(b=>b.onclick=()=>{const [uid,to]=b.dataset.evolve.split(':');g.evolvePartner(uid,Number(to)).catch(e=>g.fail(e));});
 }

 moveDetails(m){return '<span class="tag" style="--type:'+TYPE_COLORS[m.type]+'">'+esc(entity('types',m.type))+'</span><strong>'+esc(m.name)+'</strong><span class="move-stats">'+esc(t('moves.stats',{power:m.engine?.power??m.power??0,cooldown:cooldownText(m)}))+'</span><small>'+esc(m.effectDescription||m.description||'')+'</small>';}
 moves(){const g=this.game,p=g.save.collection.find(p=>p.uid===g.moveManagerUid);if(!p)return;ensureMoveState(p,g.byId.get(p.id),g.moveById);$('#panel-body').innerHTML='<p class="notice">'+esc(t('moves.managerIntro',{pokemon:g.byId.get(p.id).name}))+'</p><h3>'+t('moves.current')+'</h3><div class="move-slot-grid">'+Array.from({length:4},(_,i)=>'<div class="move-slot"><span class="eyebrow">'+t('moves.slot',{slot:i+1})+'</span>'+(p.moveIds[i]?this.moveDetails(g.moveById.get(p.moveIds[i])):'<strong>'+t('moves.empty')+'</strong>')+'</div>').join('')+'</div><h3>'+t('moves.available')+'</h3><div class="move-library">'+p.knownMoveIds.map(id=>g.moveById.get(id)).filter(Boolean).map(m=>'<button class="move-option" data-choose-move="'+m.id+'" '+(p.moveIds.includes(m.id)?'disabled':'')+'>'+this.moveDetails(m)+'<b>'+(p.moveIds.includes(m.id)?t('moves.equipped'):p.pendingMoveIds.includes(m.id)?t('moves.newChoice'):t('moves.select'))+'</b></button>').join('')+'</div><button id="moves-back" class="text-button">'+t('moves.back')+'</button>';document.querySelectorAll('[data-choose-move]').forEach(b=>b.onclick=()=>g.showMoveChoice(p.uid,Number(b.dataset.chooseMove)));$('#moves-back').onclick=()=>g.openPanel('party');}
 moveChoice(p,id,automatic){
  const g=this.game,m=g.moveById.get(id),compact=(move,label)=>'<span class="move-choice-meta"><span class="eyebrow">'+esc(label)+'</span><span class="tag" style="--type:'+TYPE_COLORS[move.type]+'">'+esc(entity('types',move.type))+'</span></span><strong>'+esc(move.name)+'</strong><span class="move-stats">'+esc(t('moves.stats',{power:move.engine?.power??move.power??0,cooldown:cooldownText(move)}))+'</span>';
  this.shell(t('moves.choiceHeading',{pokemon:g.byId.get(p.id).name}),t('moves.kicker'));$('#panel').classList.add('move-choice-panel');
  const description=m.effectDescription||m.description||'';
  $('#panel-body').innerHTML='<article id="new-move" class="new-move">'+compact(m,t('moves.candidate'))+(description?'<details class="move-choice-description"><summary>'+esc(currentLocale()==='en-US'?'Move details':'효과 자세히')+'</summary><p>'+esc(description)+'</p></details>':'')+'</article><p class="notice">'+t('moves.choiceHint')+'</p><div class="move-slot-grid">'+Array.from({length:4},(_,i)=>{const old=g.moveById.get(p.moveIds[i]);return '<button class="move-option" data-replace-slot="'+i+'" '+(i>p.moveIds.length?'disabled':'')+' aria-label="'+esc(old?t('moves.replaceAria',{old:old.name,next:m.name}):t('moves.learnAria',{next:m.name,slot:i+1}))+'">'+(old?compact(old,t('moves.slot',{slot:i+1})):'<span class="eyebrow">'+t('moves.slot',{slot:i+1})+'</span><strong>'+t('moves.empty')+'</strong>')+'<b>'+(old?t('moves.replace'):t('moves.learn'))+'</b></button>';}).join('')+'</div><div class="move-choice-actions"><button id="move-decline" class="text-button">'+(automatic?t('moves.decline'):t('moves.cancel'))+'</button>'+(automatic?'<button id="move-later" class="text-button">'+t('moves.later')+'</button>':'')+'</div><p class="section-caption">'+t('moves.relearnHint')+'</p>';
  document.querySelectorAll('[data-replace-slot]').forEach(b=>b.onclick=()=>g.resolveMoveChoice(Number(b.dataset.replaceSlot)));$('#move-decline').onclick=()=>automatic?g.resolveMoveChoice(null):g.manageMoves(p.uid);$('#move-later')?.addEventListener('click',()=>g.closePanel());
 }
 water(){const g=this.game,source=supplies.WATER_SOURCES.find(s=>s.id===g.supplySource);if(!source){g.closePanel();return;}$('#panel-title').textContent=source.name;$('#panel-body').innerHTML=`<div class="supply-water"><p>💧 마실 수 있는 수원</p><p>직접 마시면 갈증을 채우고, 물통은 따로 충전해 다음 탐험에 가져가세요.</p><div id="water-state"></div><div class="supply-actions"><button id="source-drink">직접 마시기</button><button id="source-fill">물통 채우기</button></div><p class="notice">${source.condition||'발견한 식수대에서 언제든 준비할 수 있어요.'}</p></div>`;$('#source-drink').onclick=()=>g.waterAction('drink');$('#source-fill').onclick=()=>g.waterAction('fill');this.updateWater();}
 updateWater(){if(this.game.panel!=='water'||!$('#water-state'))return;const g=this.game,s=g.save;$('#water-state').textContent=`갈증 ${Math.round(s.survival.thirst)}/100 · 물통 ${s.inventory.canteen}/${s.survival.provisions.capacity}회`;$('#source-drink').disabled=g.supplyBlocked()||s.survival.thirst>=100;$('#source-fill').disabled=g.supplyBlocked()||s.inventory.canteen>=s.survival.provisions.capacity;}
 bag(){renderBag(this);}
 shop(){this.inventory(true);}
 inventory(shop){const g=this.game,items=shop?Object.entries({...BALLS,...ITEMS}).filter(([,item])=>!item.portable):Object.entries({...BALLS,...ITEMS}).filter(([id])=>id==='canteen'||(g.save.inventory[id]||0)>0);$('#panel-body').innerHTML=`<div class="section-caption"><span>${shop?t('bag.shopIntro'):t('bag.useIntro')}</span><b>${t('common.funds',{ amount:g.save.coins.toLocaleString() })}</b></div><div class="bag-grid">${items.map(([id,item])=>`<article class="item-card"><span class="quantity">${id==='canteen'?`${g.save.inventory.canteen}/${g.save.survival.provisions.capacity}회`:'×'+(g.save.inventory[id]||0)}</span><b>${BALLS[id]?`<span class="bag-ball-icon" aria-hidden="true">${ballArtwork(id)}</span>`:''}${esc(item.name)}</b><small>${item.description|| (BALLS[id]?`${t('bag.catchMultiplier',{ multiplier:BALLS[id].multiplier })}`:t('bag.researchItem'))}</small>${shop?`<button data-buy="${id}" ${g.save.coins<item.price?'disabled':''}>${t('bag.buy',{ price:item.price })}</button>`:`<button data-use="${id}" ${item.portable&&(!(g.save.inventory[id]>0)||g.save.survival[id==='canteen'?'thirst':'hunger']>=100)?'disabled':''}>${BALLS[id]?(g.ball===id?t('bag.ballSelected'):t('bag.selectBall')):item.portable?(id==='canteen'?'물통 1회분 마시기':'먹기'):['potion','revive','rare-candy'].includes(id)?t('bag.useItem'):t('bag.viewParty')}</button>`}</article>`).join('')}</div><div class="notice">${esc(supplies.supplyAdvice(g))}<br>기본 식량: ${supplies.rationReason(g.save)||'캠프 보급 상자에서 받을 수 있어요'}. 휴대 음식 ${supplies.SUPPLY_RULES.campFoodLimit}개까지, 모든 캠프 공통 ${supplies.SUPPLY_RULES.campRefill}초 간격.<br>파란 물방울 표식만 식수대예요. 화산·연구단지에는 기본 수원이 없어요.</div>`;document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>g.buy(b.dataset.buy));document.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>{const id=b.dataset.use;if(!BALLS[id]&&!ITEMS[id]?.portable&&!['potion','revive','rare-candy'].includes(id))g.openPanel('party');else g.useItem(id);});}
 map(){renderAtlas(this);}

 expeditions(){renderJourneyPanel(this);}
 research(){const g=this.game,encounters=g.biomeById.get(g.save.region).specialEncounters;$('#panel-body').innerHTML=`<p class="notice">A field journal full of discoveries opens new research opportunities. Fossil restoration and companion encounters can be repeated.</p><div class="quest-list">${encounters.map((a,i)=>`<article class="quest-row"><h3>${g.byId.get(a.speciesId).name} · ${niceLocal(a.method)}</h3><p>${g.byId.get(a.speciesId).habitatHint}</p><p>${g.requirementText(a.requirements)}</p><button data-quest="${i}" ${requirementsMet(a.requirements,g.save)?'':'disabled'}>${a.method==='fossil'?t('research.restore'):t('research.begin')}</button></article>`).join('')}</div>`;document.querySelectorAll('[data-quest]').forEach(b=>b.onclick=()=>g.specialEncounter(encounters[Number(b.dataset.quest)]).catch(e=>g.fail(e)));renderJourneyPanel(this);}
 settings(){const g=this.game;$('#panel-body').innerHTML=`<div class="settings-row"><span>Music & sound</span><input id="volume" aria-label="${esc(t('settings.volumeAria'))}" type="range" min="0" max="1" step=".05" value="${g.save.settings.volume}"></div><div class="settings-row"><span>Graphics quality</span><select id="quality"><option value="auto">Adaptive</option><option value="high">High</option><option value="low">Performance</option></select></div><div class="settings-row"><span>Camera sensitivity</span><input id="sensitivity" aria-label="${esc(t('settings.camera'))}" type="range" min=".3" max="2" step=".1" value="${g.save.settings.camera}"></div><div class="settings-row"><label for="motion">Camera impact effects</label><input id="motion" type="checkbox" ${g.save.settings.motion?'checked':''}></div><p class="notice touch-help">${t('controls.touchHelp')}</p><p class="notice">${t('controls.attackHint')}</p><div class="controls-grid">${[['W A S D',t('controls.move')],[t('controls.mouse'),t('controls.orbit')],[t('controls.wheel'),t('controls.zoom')],['Shift',t('controls.sprint')],['Space',t('controls.dodge')],['1 2 3 4',t('controls.moves')],['Tab / Q',t('controls.target')],['Shift+Tab',t('controls.targetPrevious')],['R',t('controls.throw')],['E',t('controls.interact')],['P / B',t('controls.partyBag')],['J / M',t('controls.dexMap')],['Escape',t('controls.pause')]].map(([k,v])=>`<span><kbd>${k}</kbd> ${v}</span>`).join('')}</div><div class="pause-actions"><button id="export-save" ${g.save.starter?'':'disabled'}>Export save</button><button id="import-save">Import save</button></div><input id="save-file" type="file" accept=".json,application/json" class="hidden"><p class="notice">Your expedition saves on this browser, with a recovery copy. Export a save to keep a portable backup. Importing replaces this browser’s current expedition after validation.</p>`;$('#panel-body').insertAdjacentHTML('afterbegin',`<div class="settings-row"><label for="locale">${t('ui.language')}</label><select id="locale"><option value="ko-KR">한국어</option><option value="en-US">English</option></select></div><div class="settings-row"><label for="shake">${currentLocale()==='ko-KR'?'화면 흔들림 강도':'Camera shake intensity'}</label><input id="shake" type="range" min="0" max="1" step=".05" value="${g.save.settings.shake??.65}"></div>`);$('#locale').value=g.save.settings.locale;$('#locale').onchange=e=>{g.save.settings.locale=e.target.value;setLocale(e.target.value);g.persist();if(g.phase==='title')this.ready();if(g.phase==='starter')this.showStarter();this.panel('settings');this.movesChanged();this.regionChanged(g.biomeById.get(g.save.region));localizeDOM();};$('#shake').oninput=e=>{g.save.settings.shake=Number(e.target.value);g.persist();};$('#quality').value=g.save.settings.quality;$('#volume').oninput=e=>{g.save.settings.volume=Number(e.target.value);g.audio.start();g.audio.setVolume(g.save.settings.volume);g.persist();};$('#quality').onchange=e=>{g.save.settings.quality=e.target.value;g.world.setQuality(e.target.value);g.persist();};$('#sensitivity').oninput=e=>{g.save.settings.camera=Number(e.target.value);g.persist();};$('#motion').onchange=e=>{g.save.settings.motion=e.target.checked;g.persist();};$('#export-save').onclick=()=>this.exportSave();$('#import-save').onclick=()=>$('#save-file').click();$('#save-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>8e6)throw Error(t('save.tooLarge'));const imported=migrateFiveSave(await file.text(),g.compositions);if(!imported.starter)throw Error(t('save.noStarter'));this.pendingImport=imported;this.confirmImport();}catch(e){this.toast(t('save.importFailed'),e.message,true);}};}
 confirmImport(){this.shell(t('save.importHeading'),t('save.importKicker'));const s=this.pendingImport;$('#panel-body').innerHTML=`<p>${t('save.importSummary',{ species:caughtCount(s),companions:s.collection.length,region:niceLocal(s.region) })}</p><p class="notice">This replaces your current expedition. You can export the current save before continuing.</p><div class="pause-actions"><button id="backup-import">Export current save</button><button id="apply-import">Import this expedition</button><button id="cancel-import">Cancel</button></div>`;localizeDOM($('#panel'));$('#backup-import').onclick=()=>this.exportSave();$('#cancel-import').onclick=()=>this.game.openPanel('settings');$('#apply-import').onclick=async()=>{const g=this.game;g.save=s;setLocale(s.settings.locale);g.player=null;initializeCheckpoint(g);g.audio.setVolume(s.settings.volume);g.world.setQuality(s.settings.quality);await g.enterRegion(s.region,s.position);g.persist();this.pendingImport=null;};}
 exportSave(){this.game.syncPlayer();const text=serialize(this.game.save),url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`kanto151-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);this.toast(t('save.exported'),t('save.keepFile'));}
 recoveryError(message){this.shell('탐험 기록 복귀 대기','저장대 기록 유지');$('#panel-body').innerHTML='<p>복귀를 마치지 못해 진행을 멈췄어요. 마지막 저장대 기록과 자동 저장은 덮어쓰지 않았어요.</p><p>'+esc(message)+'</p><button id="retry-recovery">같은 기록으로 복귀 다시 시도</button>';$('#retry-recovery').onclick=()=>{this.game.survivalDying=false;restoreCheckpoint(this.game);};}
 pause(){const g=this.game;$('#panel-body').innerHTML=`<div class="capture-card"><span class="eyebrow">${g.biomeById.get(g.save.region)?.name||t('app.shortName')}</span><h2>${num(caughtCount(g.save))} <small>/ 151</small></h2><p>${t('pause.playtime',{ hours:Math.floor(g.save.playTime/3600),minutes:Math.floor(g.save.playTime/60)%60,count:g.save.collection.length })}</p></div><div class="pause-actions"><button id="resume">Keep exploring</button><button id="save-now">이어하기 기록 저장</button><button id="pause-settings">Settings</button><button id="pause-credits">Credits</button><button id="return-camp" ${returnBlock(g)?'disabled':''}>이 지역 쉼터로 귀환</button><button id="title-return">이어하기 저장 후 첫 화면</button></div><p class="notice">${esc(returnBlock(g)||'귀환은 이동만 합니다. 쉼터의 쉬기로 회복하고 음식·물은 따로 준비하세요.')}</p><p class="notice checkpoint-summary">${esc(checkpointSummary(g))}</p><p class="notice">자동 저장·메뉴 저장은 일반 이어하기용이에요. 생존 고갈로 사망하면 마지막 저장대의 전체 기록으로 돌아가며, 이후 얻은 포켓몬·아이템·경험치·보상·진행은 되돌아가요. 복귀 기록은 저장대에서 E로 갱신하세요.</p>`;$('#resume').onclick=()=>g.closePanel();$('#save-now').onclick=()=>g.persist();$('#pause-settings').onclick=()=>g.openPanel('settings');$('#pause-credits').onclick=()=>g.openPanel('credits');$('#return-camp').onclick=()=>g.returnToCamp().catch(e=>g.fail(e));$('#title-return').onclick=async()=>{const button=$('#title-return');if(button.disabled)return;button.disabled=true;if(g.persist()!==true){button.disabled=false;const notice=document.createElement('p');notice.className='notice save-error';notice.setAttribute('role','alert');notice.textContent=currentLocale()==='ko-KR'?'저장하지 못했어요. 이 화면을 유지합니다. 다시 저장하거나 설정에서 기록을 내보내세요.':'Save failed. Your expedition stays here. Retry saving or export it in Settings.';$('#panel-body .save-error')?.remove();$('#panel-body').append(notice);return;}g.closePanel();g.phase='loading';this.loading(t('loading.returnCamp'));await g.world.build(g.biomeById.get(g.homeRegion));await g.loadShowcase();g.phase='title';$('#hud').classList.add('hidden');this.ready();};}
 credits(){$('#panel-body').innerHTML=`<div class="credits"><p>Kanto 151 is a private, noncommercial Pokémon fan project for TCG Hub. Pokémon names and characters belong to Nintendo, Game Freak and Creatures. This project is not affiliated with or endorsed by them.</p><h2>Pokémon models, textures & animations</h2><p>Cobblemon team and contributing artists. <a href="https://gitlab.com/cable-mc/cobblemon-assets" target="_blank" rel="noreferrer">Cobblemon Assets</a> — <a href="https://creativecommons.org/licenses/by-nc/3.0/" target="_blank" rel="noreferrer">CC BY-NC 3.0</a>. Original Bedrock files are adapted at runtime for web rendering. Per-species licenses, authors, hashes and conversion details are preserved in the local asset records.</p><h2>The world</h2><p><a href="https://quaternius.com/packs/stylizednaturemegakit.html" target="_blank" rel="noreferrer">Quaternius Stylized Nature MegaKit Standard</a>, <a href="https://kenney.nl/assets/nature-kit" target="_blank" rel="noreferrer">Kenney Nature Kit</a> and <a href="https://kenney.nl/assets/survival-kit" target="_blank" rel="noreferrer">Kenney Survival Kit</a> — CC0 1.0. Landscape, water, atmosphere and composition created for this expedition.</p><h2>Data & technology</h2><p><a href="https://github.com/PokeAPI/pokeapi" target="_blank" rel="noreferrer">PokéAPI</a> source data — BSD 3-Clause. <a href="https://threejs.org/" target="_blank" rel="noreferrer">Three.js</a> r180 — MIT. Data is cached locally. Original synthesized music and sound effects; no official game audio or ripped official game models are used.</p><h2>Preserved records</h2><p><a href="./CREDITS.md" target="_blank">Full credits</a> · <a href="./reports/asset-audit.json" target="_blank">151 asset audit</a> · <a href="./reports/validation.json" target="_blank">Progression validation</a></p><button id="open-assets" class="text-button">Developer asset test room →</button></div>`;$('#open-assets').onclick=()=>this.game.openPanel('assets');}
 evolutionResult(previous,p){this.game.panel='evolution-result';this.shell(t('evolution.heading'),t('evolution.kicker'));const next=this.game.byId.get(p.id);$('#panel-body').innerHTML=`<div class="evolution-pair"><div class="evolution-before"><canvas id="evolution-before" class="preview-canvas" aria-label="${t('evolution.beforeAria',{ pokemon:previous.name })}"></canvas><span class="eyebrow">#${num(previous.id)}</span><h2>${previous.name}</h2></div><div class="evolution-after"><canvas id="evolution-after" class="preview-canvas" aria-label="${t('evolution.afterAria',{ pokemon:next.name })}"></canvas><span class="eyebrow">#${num(next.id)} ${p.shiny?'· ✦ SHINY':''}</span><h2>${next.name}</h2>${tags(next)}</div></div><div class="capture-card"><p>Your partner keeps its identity, level and shiny appearance.<br>Both species stay recorded in your journal.</p><p id="evolution-dex-count">${t('dex.registrations',{count:caughtCount(this.game.save)})}</p><button id="evolution-continue" class="primary">Keep exploring <span>↗</span></button></div>`;this.preview($('#evolution-before'),previous.id,p.shiny);this.preview($('#evolution-after'),p.id,p.shiny);localizeDOM($('#panel'));$('#evolution-continue').onclick=()=>this.game.closePanel();}
 captureResult(p,fresh){this.game.panel='capture-result';this.shell(fresh?t('capture.newHeading'):t('capture.repeatHeading'),fresh?t('capture.registration'):t('capture.updated'));const s=this.game.byId.get(p.id);$('#panel-body').innerHTML=`<div class="capture-card"><canvas id="capture-preview" class="preview-canvas" aria-label="${t('capture.modelAria',{ pokemon:s.name })}"></canvas><span class="eyebrow">#${num(p.id)} ${p.shiny?'· ✦ SHINY':''}</span><h2>${s.name}</h2>${tags(s)}<p>${t('common.levelLabel',{ level:p.level })} · ${s.genus}<br>${t('dex.registrations',{ count:caughtCount(this.game.save) })}</p><button id="capture-continue" class="primary">Keep exploring <span>↗</span></button></div>`;this.preview($('#capture-preview'),p.id,p.shiny);localizeDOM($('#panel'));$('#capture-continue').onclick=()=>this.game.closePanel();}
 completion(){this.game.panel='complete';this.shell(t('completion.heading'),t('completion.kicker'));$('#panel-body').innerHTML='<div class="capture-card"><span class="eyebrow">THE KANTO EXPEDITION</span><h2>151 / 151</h2><p>From your first partner to the last hidden memory.<br>Every species now has a place in your field journal.</p><p>Keep exploring for shiny partners, train your favourites,<br>or return to the sanctuaries whenever you like.</p><button id="complete-export" class="primary">Export your completed journal ↗</button><button id="complete-continue" class="text-button">There is still more to discover</button></div>';localizeDOM($('#panel'));$('#complete-export').onclick=()=>this.exportSave();$('#complete-continue').onclick=()=>this.game.closePanel();this.game.audio.play('evolution');}
 assets(){const g=this.game,id=this.assetId,s=g.byId.get(id),a=g.manifest.find(x=>x.id===id);$('#panel-body').innerHTML=`<div class="asset-nav"><button id="asset-prev">← Previous</button><select id="asset-select" aria-label="${esc(t('assets.speciesAria'))}">${g.species.map(s=>`<option value="${s.id}">#${num(s.id)} ${s.name}</option>`).join('')}</select><button id="asset-next">Next →</button><button id="asset-audit">Validate all 151</button></div><div class="asset-row"><div><span class="eyebrow">NORMAL</span><canvas id="asset-normal" class="preview-canvas"></canvas></div><div><span class="eyebrow">SHINY</span><canvas id="asset-shiny" class="preview-canvas"></canvas></div></div><div class="panel-toolbar"><select id="asset-animation" aria-label="${esc(t('assets.animationAria'))}"><option value="">Idle (automatic)</option>${a.animations.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('')}</select><span id="asset-result">${a.runtimeLoadStatus}</span></div><div class="asset-facts"><div><b>GEOMETRY / TEXTURES</b>${t('assets.bonesCubes',{ bones:a.geometry.bones,cubes:a.geometry.cubes })}<br>${a.geometry.textureWidth} × ${a.geometry.textureHeight}</div><div><b>LAYERS / FORMS</b>${t('assets.variantCount',{ count:a.variants.length })} · ${a.genderVariants?t('assets.genderVariants'):t('assets.standard')}<br>${a.emissive?'Emissive · ':''}${a.animatedTexture?t('assets.animatedTextures'):t('assets.staticTextures')}</div><div><b>SCALE / GROUND</b>Native Bedrock units ÷ 16; capped display size.<br>Ground-aligned y = 0. Drag previews to rotate.</div><div><b>SOURCE / LICENSE</b><a href="${a.source}" target="_blank" rel="noreferrer">Cobblemon · #${num(id)} ${s.name}</a><br>${a.license}</div><div><b>NORMAL TEXTURE</b>${a.texture}</div><div><b>SHINY TEXTURE</b>${a.shinyTexture}</div></div>`;$('#asset-select').value=id;$('#asset-select').onchange=e=>{this.assetId=+e.target.value;this.panel('assets');};$('#asset-prev').onclick=()=>{this.assetId=id===1?151:id-1;this.panel('assets');};$('#asset-next').onclick=()=>{this.assetId=id===151?1:id+1;this.panel('assets');};this.preview($('#asset-normal'),id);this.preview($('#asset-shiny'),id,true);$('#asset-animation').onchange=e=>{for(const p of this.previews)p.animation=e.target.value||null;};$('#asset-audit').onclick=()=>this.runAssetAudit();}
 async runAssetAudit(){const button=$('#asset-audit');button.disabled=true;const results=[];for(const s of this.game.species){if(this.game.panel!=='assets')break;try{const m=await this.game.resources.create(s.id,{maxDimension:3.2});this.game.world.actors.add(m);m.position.set(0,0,0);m.userData.update(.1,{moving:true});this.game.world.renderer.render(this.game.world.scene,this.game.world.camera);await m.userData.setShiny(true);m.userData.update(.1,{});const box=new THREE.Box3().setFromObject(m);if(!Number.isFinite(box.max.y)||box.isEmpty())throw Error(t('assets.invalidBounds'));this.game.world.actors.remove(m);m.userData.release();results.push({id:s.id,passed:true});}catch(e){results.push({id:s.id,passed:false,error:e.message});}if($('#asset-result'))$('#asset-result').textContent=t('assets.progress',{count:results.length,errors:results.filter(r=>!r.passed).length});await new Promise(requestAnimationFrame);}this.game.assetRuntimeResults=results;if(button.isConnected)button.disabled=false;this.toast(t('assets.runtimeValidation'),t('assets.result',{passed:results.filter(r=>r.passed).length,errors:results.filter(r=>!r.passed).length}));}
 update(dt){for(const p of this.previews){if(p.model){p.elapsed+=dt;p.model.rotation.y=p.angle;p.model.userData.update?.(dt,{action:p.animation,animation:p.animation,time:p.elapsed});}p.renderer.render(p.scene,p.camera);}const g=this.game;if(g.phase!=='playing'||!g.player)return;const player=g.player;this.fitMoveLabels();const candidates=[];for(const a of g.wild){const d=a.model.position.distanceTo(player.model.position),pt=g.world.project(a.model.position.clone().add(new THREE.Vector3(0,(a.model.userData.height||1)+.55,0)));a.label.classList.toggle('selected-target',g.target===a);a.label.style.display=pt.visible&&d<25&&!a.capturing&&a.hp>0?'block':'none';a.label.style.left=pt.x+'px';a.label.style.top=pt.y+'px';if(this.updateTimer-dt<=0)a.label.innerHTML=(a.shiny?'✦ ':'')+esc(a.species.name)+' <small>Lv.'+a.level+'</small>'+(a.hp<a.maxHp?'<div class="tiny-hp"><i style="width:'+a.hp/a.maxHp*100+'%"></i></div>':'');if(a.label.style.display==='block'){const r=a.label.getBoundingClientRect();candidates.push({id:a.id+':'+g.wild.indexOf(a),actor:a,selected:g.target===a,distance:d,x:r.x,y:r.y,w:r.width,h:r.height});}}const obstacles=[...document.querySelectorAll('#target-hud,#boss-hud,.partner-card,.minimap-wrap,#objective,#context,#moves,#touch-controls')].filter(el=>getComputedStyle(el).display!=='none'&&!el.classList.contains('hidden')).map(el=>{const r=el.getBoundingClientRect();return{x:r.x,y:r.y,w:r.width,h:r.height};}).filter(r=>r.w&&r.h&&r.w<innerWidth*.95);const visibleLabels=visibleWildLabels(candidates,obstacles,{width:innerWidth,height:innerHeight});for(const c of candidates)if(!visibleLabels.has(c.id))c.actor.label.style.display='none';this.updateTimer-=dt;if(this.updateTimer>0)return;this.updateTimer=.1;this.updateWater();const survival=g.save.survival||{hunger:100,thirst:100};if(!$('#portable-supplies')){$('#survival-status').insertAdjacentHTML('beforeend','<button id="portable-supplies" aria-label="가방의 음식과 물통 열기"></button>');$('#portable-supplies').onclick=()=>g.openPanel('bag');}$('#portable-supplies').textContent=`물 ${g.save.inventory.canteen}/${survival.provisions.capacity} · 식량 ${supplies.foodCount(g.save)} ▸`;$('#portable-supplies').title=supplies.supplyAdvice(g);for(const [kind,value] of [['hunger',survival.hunger],['thirst',survival.thirst]]){const percent=Math.max(0,Math.min(100,Number(value)||0));$('#'+kind+'-label').textContent=t('survival.'+kind);$('#'+kind+'-value').textContent=String(Math.round(percent));$('#'+kind+'-fill').style.width=percent+'%';$('#'+kind+'-fill').style.background=percent<20?'#f49377':kind==='thirst'?'#80d0e7':'#e8cb86';}$('#survival-status').classList.toggle('critical',survival.hunger<20||survival.thirst<20);$('#survival-status').setAttribute('aria-label',t('survival.hunger')+' '+Math.round(survival.hunger)+', '+t('survival.thirst')+' '+Math.round(survival.thirst));$('#world').dataset.diagnostics=JSON.stringify({player:player.model.position.toArray(),hp:player.hp,wild:g.wild.map(a=>({id:a.id,hp:a.hp,pos:a.model.position.toArray(),height:a.model.userData.height,visible:a.model.visible,action:a.action,stagger:a.recoil?.duration||0,status:a.status,behavior:a.behavior})),feedback:g.feedback.events.slice(-6),locale:currentLocale(),playTime:g.save.playTime,survival:{hunger:survival.hunger,thirst:survival.thirst,drops:survival.drops?.length||0},frameMs:g.frameTimes?.length?Math.round(g.frameTimes.reduce((a,b)=>a+b,0)/g.frameTimes.length*1000):0,landmarks:g.expedition?.state.landmarks||[],calls:g.world.renderer.info.render.calls});$('#dex-count').innerHTML=`${num(caughtCount(g.save))} <i>/151</i>`;$('#partner-name').textContent=player.species.name+(player.pokemon.shiny?' ✦':'');$('#partner-level').textContent=`LV ${player.level}`;$('#partner-hp').style.width=`${clampPercent(player.hp/player.maxHp)}%`;$('#partner-hp').style.background=player.hp/player.maxHp<.25?'#ff967d':'#b3e79c';$('#partner-health').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;this.partnerArtwork(player);const status=$('#partner-status');status.hidden=!player.status;status.textContent=player.status?niceLocal(player.status):'';$('#partner-exp').style.width=`${clampPercent(player.pokemon.exp/expNeeded(player.level))}%`;$('#ball-count').textContent=g.save.inventory[g.ball]||0;if(this.ballArtworkKind!==g.ball){this.ballArtworkKind=g.ball;$('#throw-button .ball-icon').innerHTML=ballArtwork(g.ball);}const ballLabel=entity('items',g.ball)+' · '+$('#ball-count').textContent+' · '+t('controls.throw');$('#throw-button').setAttribute('aria-label',ballLabel);$('#throw-button').setAttribute('data-i18n-aria-label',ballLabel);$('#throw-button').title=ballLabel;$('#throw-button').setAttribute('data-i18n-title',ballLabel);const hour=Math.floor(g.save.worldTime),minute=Math.floor(g.save.worldTime%1*60);$('#world-clock').textContent=`${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')} · ${niceLocal(g.save.weather)} ${hour<6||hour>=19?'· '+niceLocal('night'):''}`;document.querySelectorAll('[data-move]').forEach((b,i)=>{const c=g.cooldowns[i]||0;b.querySelector('.cooldown').style.height=`${clampPercent(c/cooldownSeconds(g.activeMoves[i]))}%`;b.querySelector('em').textContent=c>0?remainingText(c):({electric:'ϟ',water:'≈',fire:'♨',grass:'❧',ice:'❄',psychic:'◎',ghost:'☽',dragon:'✧'}[g.activeMoves[i].type]||'◇');});const target=g.target&&g.wild.includes(g.target)?g.target:null;const incoming=g.wild.some(a=>a.hp>0&&!a.capturing&&a.model.position.distanceTo(player.model.position)<16&&(a.angry||a.action==='attack'));if(target||incoming||player.hit>0)this.lastCombat=g.save.playTime;const combat=!!target||incoming||g.save.playTime-(this.lastCombat??-99)<3;if(this.hudCombat!==combat){this.hudCombat=combat;this.skillBarOverride=null;}const skillsOpen=this.skillBarOverride??combat;$('#hud').classList.toggle('in-combat',combat);$('#hud').classList.toggle('skills-open',skillsOpen);$('#touch-skills').setAttribute('aria-expanded',String(skillsOpen));$('#touch-skills').textContent=skillsOpen?'기술 −':'기술 +';$('#target-hud').classList.toggle('hidden',!target||target.boss);$('#boss-hud').classList.toggle('hidden',!target?.boss);if(target){if(target.boss){$('#boss-name').textContent=target.species.name;$('#boss-title').textContent=target.weakened?t('boss.barrierBroken'):t('boss.guardian');$('#boss-hp').style.width=`${clampPercent(target.hp/target.maxHp)}%`;}else{$('#target-name').innerHTML=`${esc(target.species.name)} <small>Lv. ${target.level}</small>`;$('#target-state').textContent=(target.runEncounter?'탐사 구역 방어':target.eliteId?'정예 도전':target.shiny?t('battle.shiny'):t('battle.wild'))+' · '+target.species.types.map(x=>entity('types',x)).join(' / ');$('#target-hp').style.width=`${clampPercent(target.hp/target.maxHp)}%`;$('#capture-odds').textContent=target.eliteId||target.runEncounter?`${Math.ceil(target.hp)} / ${target.maxHp} HP · 포획 불가 · 공격 예고에 회피`:`${target.status?niceLocal(target.status)+' · ':''}${Math.ceil(target.hp)} / ${target.maxHp} HP · R to throw`;}}
 const interaction=g.nearbyInteraction(),info=interactionInfo(g,interaction),visible=!!info&&!g.panel;$('#context').classList.toggle('hidden',!visible);g.world.highlightInteraction?.(visible?interaction:null);if(info){$('#context').innerHTML='<kbd>E</kbd><div><b>'+esc(info.icon+' '+info.action)+'</b><small>'+esc(info.name+(info.reason?' · '+info.reason:''))+'</small>'+(info.detail?'<small>'+esc(info.detail)+'</small>':'')+'</div>';$('#context').classList.toggle('unavailable',!!info.reason);$('#context').classList.toggle('field-capability',interaction?.kind==='capability'||interaction?.entry?.rarity==='rare');}const touch=$('#touch-interact');touch.classList.toggle('hidden',!visible);touch.innerHTML=info?'<b>'+esc(info.icon+' '+info.action)+'</b><small>'+esc(info.reason||info.name)+'</small>'+(info.detail?'<small class="interaction-detail">'+esc(info.detail)+'</small>':''):'';touch.classList.toggle('journey-interact',['journey','elite','run','survey-hub'].includes(interaction?.kind));touch.disabled=!visible||!!info?.reason;touch.setAttribute('aria-label',info?[info.name,info.action,info.reason].join(' · '):'가까운 대상 없음');updateNavigation(this);localizeDOM(document.querySelector('#hud'));}

}
